import { useEffect, useState } from 'react';
import {
  JxBadge,
  JxSegmentedControl,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'sans' | 'serif' | 'mono';

interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceSettingsProps {
  onChange?: (value: AppearanceSettingsValue) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState<Font>('system');

  useEffect(() => {
    onChange?.({ theme, scale, dense, font });
  }, [theme, scale, dense, font, onChange]);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-6)',
        padding: 'var(--jx-space-6)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <h2 className="jx-heading">Внешний вид</h2>
        <JxBadge variant="neutral">{themeLabels[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <span className="jx-label">Тема</span>
        <JxSegmentedControl
          value={theme}
          onValueChange={(value) => setTheme(value as Theme)}
          options={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
        />
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span className="jx-label">Масштаб интерфейса</span>
          <span className="jx-text-muted">{scale}%</span>
        </div>
        <JxSlider
          min={80}
          max={140}
          step={1}
          value={scale}
          onValueChange={setScale}
          aria-label="Масштаб интерфейса"
        />
      </div>

      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
          <span className="jx-label">Плотная вёрстка</span>
          <span className="jx-text-muted">Уменьшает отступы между элементами</span>
        </div>
        <JxSwitch checked={dense} onCheckedChange={setDense} aria-label="Плотная вёрстка" />
      </div>

      <JxDivider />

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
        <h3 className="jx-heading-sm">Ещё</h3>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
          <span className="jx-label">Шрифт</span>
          <JxSelect
            value={font}
            onValueChange={(value) => setFont(value as Font)}
            options={[
              { value: 'system', label: 'Системный' },
              { value: 'sans', label: 'Без засечек' },
              { value: 'serif', label: 'С засечками' },
              { value: 'mono', label: 'Моноширинный' },
            ]}
          />
        </div>
      </div>
    </div>
  );
}

